-- The repair library (owner, Oct 6: "look at all the repairs you can choose from, ensure we have
-- the same on our side"). CenterPoint's Repair Library, read on Oct 6: 475 repairs, each with a
-- unit, a price and roof-type tags (General, BUR, Single Ply, Duro-Last …) — the same list the
-- ticket's "Select Repair" picker offers. Loaded exactly as CenterPoint has it (the owner: "load
-- exactly as is"), $0.00 prices included. The price is a manager's reference only: invoices stay
-- time + materials (owner, Oct 6), as CenterPoint's did (invoice 5431).
--
-- The 16 starter templates (20260927130000_service_field.sql) are retired (active = false), so
-- the picker shows the library; repairs already on tickets keep their own name and template.
-- "Previous Repair Failure" is in both lists and stays active with CenterPoint's price.
-- Idempotent: a repair is matched by name + unit.
alter table public.repair_templates add column if not exists tags text[] not null default '{}';
comment on column public.repair_templates.tags is
  'Roof types the repair applies to (CenterPoint Repair Library tags).';

update public.repair_templates set active = false
 where centerpoint_template_id is null
   and name in ('Drainage – Clogged Scupper/Drain','Drainage – Drain Flashing Failure',
     'Membrane – Holes','Membrane – Open Seams','Membrane – Blisters',
     'Flashing – Wall Flashing Failure','Flashing – Curb / Unit Flashing',
     'Penetration – Pipe Boot / Pipe Flashing','Penetration – Pitch Pocket',
     'Metal – Coping / Edge Metal','Metal – Screws Backing Out (metal roof)',
     'A/C – Condensate Drains on Roof','Debris Removal / Cleaning',
     'Leak Investigation / Water Test','Other Repair');

create temp table _cp_repairs (name text, category text, unit text, price numeric, tags text[]);

-- Already there (by name + unit): CenterPoint's price, tags and category; active again.
update public.repair_templates t
   set unit_price = c.price, tags = c.tags, category = coalesce(t.category, c.category),
       active = true, updated_at = now()
  from _cp_repairs c
 where t.name = c.name and t.unit = c.unit;

select c.name, c.category, c.unit, c.price, c.tags, false, true
  from _cp_repairs c
 where not exists (select 1 from public.repair_templates t where t.name = c.name and t.unit = c.unit);

-- The close-out's quick chips are the favourites, then the most used: the starter favourites carry
-- over to their CenterPoint names, so the chips are not just the first names alphabetically.
update public.repair_templates set favorite = true
 where active and name in ('Drainage - Clogged Scupper/Drain', 'Drainage - Drain Flashing Failure',
   'Membrane - Holes', 'Membrane - Open Seams', 'Perimeter - Wall flashing',
   'Penetrations - Pipe flashing failure', 'Previous Repair Failure', 'Leak Location');

drop table _cp_repairs;
